<div class="d-flex justify-content-between mb-3"><h4>Receive goods - <?= e($po['po_no']) ?></h4><a class="btn btn-outline-secondary" href="<?= url('purchasing/view', ['id' => $po['id']]) ?>">Back</a></div>
<form method="post" class="needs-validation" novalidate><?= csrf_field() ?>
<div class="row g-2 mb-3"><div class="col-md-3"><label class="form-label">Received date</label><input type="date" name="received_date" class="form-control" value="<?= date('Y-m-d') ?>" max="<?= date('Y-m-d') ?>" required></div><div class="col-md-9"><label class="form-label">Notes</label><input name="notes" maxlength="255" class="form-control"></div></div>
<div class="card"><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead class="table-light"><tr><th>Product</th><th class="text-end">Outstanding</th><th style="width:120px">Received</th><th style="width:120px">Damaged</th><th style="width:120px">Rejected</th><th style="width:250px">Batch / Expiry</th></tr></thead><tbody>
<?php foreach ($items as $i): $open = $i['qty'] - $i['received_qty']; $k = (int)$i['id']; ?><tr><td><?= e($i['sku'] . ' - ' . $i['name']) ?></td><td class="text-end"><?= fq($open) ?></td>
<td><input type="number" step="any" min="0" max="<?= fq($open) ?>" value="<?= fq($open) ?>" name="recv[<?= $k ?>]" class="form-control form-control-sm" required></td><td><input type="number" step="any" min="0" value="0" name="damaged[<?= $k ?>]" class="form-control form-control-sm"></td><td><input type="number" step="any" min="0" value="0" name="rejected[<?= $k ?>]" class="form-control form-control-sm"></td>
<td><?php if ($i['track_expiry']): ?><div class="input-group input-group-sm"><input name="batch_no[<?= $k ?>]" class="form-control" placeholder="Batch no" maxlength="40"><input type="date" name="expiry_date[<?= $k ?>]" class="form-control" title="Expiry date" <?= $i['shelf_life_days'] ? '' : 'required' ?>></div><?php else: ?><span class="text-muted small">-</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="form-text my-2">Accepted = received - damaged - rejected. Only accepted items increase sellable stock; damaged items are tracked separately. Quantities not received now stay outstanding (recorded as a shortage on this GRN).</div>
<button class="btn btn-success once"><i class="bi bi-check-lg"></i> Confirm receipt &amp; update stock</button></form>
